//go:build ignore

// gen writes consts_generated.go: typescript-go's syntax kinds and flags,
// re-declared in the shim, so the frontend layer can name every one of
// them without the shim listing them by hand. Run it after moving the
// typescript-go submodule to another release:
//
//	cd third_party/tsgo-shim && go run gen.go
package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// prefixes are the constant families the shim re-declares, by package.
var prefixes = map[string][]string{
	"ast": {"Kind", "ModifierFlags", "SymbolFlags", "NodeFlags"},
}

func main() {
	var b bytes.Buffer
	b.WriteString("// SPDX-License-Identifier: MIT\n// Copyright (c) 2026 TrendVidia, LLC.\n\n")
	b.WriteString("// Code generated by gen.go; DO NOT EDIT.\n\npackage tsgo\n\nimport (\n")
	pkgs := make([]string, 0, len(prefixes))
	for p := range prefixes {
		pkgs = append(pkgs, p)
	}
	sort.Strings(pkgs)
	for _, p := range pkgs {
		fmt.Fprintf(&b, "\t%q\n", "github.com/microsoft/typescript-go/internal/"+p)
	}
	b.WriteString(")\n\nconst (\n")
	for _, p := range pkgs {
		for _, name := range constants(p, prefixes[p]) {
			fmt.Fprintf(&b, "\t%s = %s.%s\n", name, p, name)
		}
	}
	b.WriteString(")\n")
	src, err := format.Source(b.Bytes())
	if err != nil {
		fail(err)
	}
	if err := os.WriteFile("consts_generated.go", src, 0o644); err != nil {
		fail(err)
	}
}

// constants lists a package's exported constants with one of the
// prefixes, sorted.
func constants(pkg string, want []string) []string {
	dir := filepath.Join("..", "typescript-go", "internal", pkg)
	files, err := filepath.Glob(filepath.Join(dir, "*.go"))
	if err != nil {
		fail(err)
	}
	seen := map[string]bool{}
	fset := token.NewFileSet()
	for _, f := range files {
		if strings.HasSuffix(f, "_test.go") {
			continue
		}
		file, err := parser.ParseFile(fset, f, nil, parser.SkipObjectResolution)
		if err != nil {
			fail(err)
		}
		for _, d := range file.Decls {
			g, ok := d.(*ast.GenDecl)
			if !ok || g.Tok != token.CONST {
				continue
			}
			for _, s := range g.Specs {
				for _, n := range s.(*ast.ValueSpec).Names {
					if n.IsExported() && hasPrefix(n.Name, want) {
						seen[n.Name] = true
					}
				}
			}
		}
	}
	out := make([]string, 0, len(seen))
	for n := range seen {
		out = append(out, n)
	}
	sort.Strings(out)
	return out
}

func hasPrefix(name string, prefixes []string) bool {
	for _, p := range prefixes {
		if strings.HasPrefix(name, p) {
			return true
		}
	}
	return false
}

func fail(err error) {
	fmt.Fprintln(os.Stderr, "gen:", err)
	os.Exit(1)
}
